DlgPrefVertexAV::~DlgPrefVertexAV() = default;

void DlgPrefVertexAV::slotUpdate() {
    m_pEnabled->setChecked(m_pEnabledControl->get() > 0);
    m_pName->setText(m_pConfig->getValue(ConfigKey(kGroup, QStringLiteral("name")), QStringLiteral("Mixxx")));
    m_pPort->setValue(m_pConfig->getValue(ConfigKey(kGroup, QStringLiteral("port")), 9470));
    m_pUdpPort->setValue(m_pConfig->getValue(ConfigKey(kGroup, QStringLiteral("udp_port")), 9471));
    m_pLocalOnly->setChecked(m_pConfig->getValue(ConfigKey(kGroup, QStringLiteral("local_only")), false));
    const QString security =
            m_pConfig->getValue(ConfigKey(kGroup, QStringLiteral("security")), QStringLiteral("open"));
    m_pSecurity->setCurrentIndex(qMax(0, m_pSecurity->findData(security)));
    m_pCode->setText(m_pConfig->getValueString(ConfigKey(kGroup, QStringLiteral("pairing_code"))));
    m_pLookahead->setValue(m_pConfig->getValue(ConfigKey(kGroup, QStringLiteral("lookahead_ms")), 150));
    m_pOffset->setValue(m_pConfig->getValue(ConfigKey(kGroup, QStringLiteral("output_offset_ms")), 0));
    slotSecurityChanged();
    slotReceiversChanged(m_pReceivers->get());
}

void DlgPrefVertexAV::slotApply() {
    m_pConfig->setValue(ConfigKey(kGroup, QStringLiteral("name")), m_pName->text().trimmed());
    m_pConfig->setValue(ConfigKey(kGroup, QStringLiteral("port")), m_pPort->value());
    m_pConfig->setValue(ConfigKey(kGroup, QStringLiteral("udp_port")), m_pUdpPort->value());
    m_pConfig->setValue(ConfigKey(kGroup, QStringLiteral("local_only")), m_pLocalOnly->isChecked());
    m_pConfig->setValue(ConfigKey(kGroup, QStringLiteral("security")), m_pSecurity->currentData().toString());
    m_pConfig->setValue(ConfigKey(kGroup, QStringLiteral("pairing_code")), m_pCode->text());
    m_pConfig->setValue(ConfigKey(kGroup, QStringLiteral("lookahead_ms")), m_pLookahead->value());
    m_pConfig->setValue(ConfigKey(kGroup, QStringLiteral("output_offset_ms")), m_pOffset->value());
    const bool enable = m_pEnabled->isChecked();
    if (enable != (m_pEnabledControl->get() > 0)) {
        m_pEnabledControl->set(enable ? 1.0 : 0.0);
    } else if (enable) {
        m_pSettingsChanged->set(1.0); // restart with the new settings
        m_pSettingsChanged->set(0.0);
    }
}

void DlgPrefVertexAV::slotResetToDefaults() {
    m_pEnabled->setChecked(false);
    m_pName->setText(QStringLiteral("Mixxx"));
    m_pPort->setValue(9470);
    m_pUdpPort->setValue(9471);
    m_pLocalOnly->setChecked(false);
    m_pSecurity->setCurrentIndex(0);
    m_pLookahead->setValue(150);
    m_pOffset->setValue(0);
}

void DlgPrefVertexAV::slotGenerateCode() {
    m_pCode->setText(vertexav::security::pskToCode(vertexav::security::generatePsk()));
}

void DlgPrefVertexAV::slotSecurityChanged() {
    const bool auth = m_pSecurity->currentData().toString() == QLatin1String("auth");
    m_pCode->setEnabled(auth);
    m_pGenerate->setEnabled(auth);
    if (auth && m_pCode->text().isEmpty()) {
        slotGenerateCode();
    }
}

void DlgPrefVertexAV::slotReceiversChanged(double value) {
    const int n = static_cast<int>(value);
    if (m_pEnabledControl->get() <= 0) {
        m_pStatus->setText(tr("Status: disabled"));
    } else {
        m_pStatus->setText(tr("Status: running, %n receiver(s) connected", "", n));
    }
}
